B.aco={"\u062a\u064a\u0646 \u062b\u064a\u0646\u0648":0,"\u0644\u0628\u0634 \u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u0623\u0648\u0644":1,"\u0634\u064a\u0631\u064a \u0646\u064a \u0645\u0627\u0631\u064a\u0627":2,"\u0633\u064a \u0645\u0648\u062a\u064a \u0648\u0627\u0644\u0633\u0628\u0639 \u0645\u0631\u0627\u062a":3,"\u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u0623\u0648\u0644":4,"\u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u062b\u0627\u0646\u064a":5,"\u0644\u0628\u0634 \u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u062b\u0627\u0646\u064a":6,"\u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u062b\u0627\u0644\u062b":7,"\u0623\u0631\u0628\u0635\u0627\u0644\u064a\u0646":8,"\u0646\u062a\u0628\u0639\u0643 \u064a\u0627 \u0631\u0628":9,"\u0630\u0643\u0635\u0648\u0644\u0648\u062c\u064a\u0627\u062a \u0627\u0644\u0642\u062f\u064a\u0633\u064a\u0646":10,"\u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u0631\u0627\u0628\u0639":11,"\u0645\u0642\u062f\u0645\u0629 \u0643\u0644 \u0647\u0648\u0633 - \u0648\u062c\u062f\u064a \u0628\u0634\u0627\u0631\u0629":12,"\u0625\u0633\u0645\u0648 \u0625\u0628\u0634\u0648\u064a\u0633 - \u0648\u062c\u062f\u064a \u0628\u0634\u0627\u0631\u0629":13,"\u062a\u064a\u0646 \u0623\u0648\u064a\u0647 \u0625\u0646\u0633\u0648\u0643 - \u0648\u062c\u062f\u064a \u0628\u0634\u0627\u0631\u0629":14,"\u0645\u062f\u0627\u0626\u062d \u0627\u0644\u062a\u0630\u0643\u0627\u0631 \u0627\u0644\u0633\u0646\u0648\u064a - \u0648\u062c\u062f\u064a \u0628\u0634\u0627\u0631\u0629":15,"\u0645\u0642\u062f\u0645\u0629 \u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0627\u062a \u0622\u062f\u0627\u0645 - \u0648\u062c\u062f\u064a \u0628\u0634\u0627\u0631\u0629":16,"\u0627\u0644\u0625\u0646\u062c\u064a\u0644 - \u0648\u062c\u062f\u064a \u0628\u0634\u0627\u0631\u0629":17,"\u0622\u0645\u064a\u0646 \u0643\u064a\u0631\u064a \u0625\u0644\u064a\u0633\u0648\u0646 - \u0648\u062c\u062f\u064a \u0628\u0634\u0627\u0631\u0629":18,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u0623\u062d\u062f":19,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u0623\u062d\u062f - \u0623\u064a\u0643\u0648\u062a\u064a":20,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u0627\u062b\u0646\u064a\u0646":21,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u0627\u0644\u0627\u062b\u0646\u064a\u0646":22,"\u062e\u062a\u0627\u0645 \u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u0627\u0644\u0622\u062f\u0627\u0645":23,"\u0630\u0643\u0635\u0648\u0644\u0648\u062c\u064a\u0629 \u0628\u0627\u0643\u0631":24,"\u062a\u064a\u0646 \u062b\u064a\u0646\u0648 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":25,"\u062a\u064a\u0646\u0627\u0641 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":26,"\u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u0623\u0648\u0644 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":27,"\u0634\u064a\u0631\u064a \u0646\u064a \u0645\u0627\u0631\u064a\u0627 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":28,"\u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u062b\u0627\u0646\u064a - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":29,"\u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u062b\u0627\u0644\u062b - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":30,"\u0623\u0631\u0628\u0635\u0627\u0644\u064a\u0646 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":31,"\u0644\u0628\u0634 \u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u0623\u0648\u0644 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":32,"\u0644\u0628\u0634 \u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u062b\u0627\u0646\u064a - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":33,"\u0645\u062c\u0645\u0639 \u0627\u0644\u0642\u062f\u064a\u0633\u064a\u0646 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":34,"\u0646\u062a\u0628\u0639\u0643 \u064a\u0627 \u0631\u0628 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":35,"\u0630\u0643\u0635\u0648\u0644\u0648\u062c\u064a\u0627\u062a \u0627\u0644\u0642\u062f\u064a\u0633\u064a\u0646 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":36,"\u0627\u0644\u0647\u0648\u0633 \u0627\u0644\u0631\u0627\u0628\u0639 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":37,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0622\u062f\u0627\u0645 \u0644\u0644\u0642\u064a\u0627\u0645\u0629 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":38,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u062b\u0644\u0627\u062b\u0627\u0621 - \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0639\u0631\u0628\u064a":39,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u062b\u0644\u0627\u062b\u0627\u0621":40,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u0627\u0644\u062b\u0644\u0627\u062b\u0627\u0621 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":41,"\u0646\u064a\u0645 \u063a\u0627\u0631 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":42,"\u0644\u0628\u0634 \u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u0627\u0644\u062b\u0644\u0627\u062b\u0627\u0621 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":43,"\u0646\u064a\u0643\u0646\u0627\u064a \u0623\u0648 \u0628\u0627\u0646\u0648\u062a\u064a - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":44,"P2 - \u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u062b\u0644\u0627\u062b\u0627\u0621":45,"\u0630\u0643\u0635\u0648\u0644\u0648\u062c\u064a\u0629 \u0628\u0627\u0643\u0631 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":46,"\u0630\u0648\u0643\u0635\u0648\u0644\u0648\u062c\u064a\u0629 \u0644\u0644\u0639\u0630\u0631\u0627\u0621 \u0645\u0631\u064a\u0645 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":47,[u.I]:48,[u.ax]:49,[u.au]:50,"\u0630\u0648\u0643\u0635\u0648\u0644\u0648\u062c\u064a\u0629 \u0644\u0644\u0633\u0645\u0627\u0626\u064a\u064a\u0646 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":51,[u.cU]:52,[u.Z]:53,"\u0630\u0648\u0643\u0635\u0648\u0644\u0648\u062c\u064a\u0629 \u0644\u0645\u0627\u0631 \u0645\u0631\u0642\u0633 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":54,[u.cg]:55,"\u0630\u0648\u0643\u0635\u0648\u0644\u0648\u062c\u064a\u0629 \u0644\u0645\u0627\u0631 \u062c\u0631\u062c\u0633 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":56,[u.c0]:57,[u.F]:58,[u.cF]:59,[u.cA]:60,[u.a0]:61,[u.H]:62,"\u0630\u0648\u0643\u0635\u0648\u0644\u0648\u062c\u064a\u0629 \u0644\u0644\u0623\u0646\u0628\u0627 \u0628\u0648\u0644\u0627 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":63,[u.bS]:64,[u.L]:65,[u.ad]:66,"\u0630\u0648\u0643\u0635\u0648\u0644\u0648\u062c\u064a\u0629 \u0644\u0644\u0623\u0628 \u0627\u0644\u0628\u0637\u0631\u064a\u0643 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":67,"\u062e\u062a\u0627\u0645 \u0627\u0644\u0630\u0648\u0643\u0635\u0648\u0644\u0648\u062c\u064a\u0627\u062a - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":68,[u.aK]:69,[u.an]:70,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u064a\u0648\u0645 \u0627\u0644\u0623\u062b\u0646\u064a\u0646 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":71,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u062b\u0644\u0627\u062b\u0627\u0621 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":72,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u0623\u0631\u0628\u0639\u0627\u0621 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":73,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u062e\u0645\u064a\u0633 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":74,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u062c\u0645\u0639\u0629 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":75,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u0633\u0628\u062a - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":76,"\u062e\u062a\u0627\u0645 \u0627\u0644\u0623\u0628\u0635\u0627\u0644\u064a\u0627\u062a \u0627\u0644\u0623\u062f\u0627\u0645 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":77,"\u062e\u062a\u0627\u0645 \u0627\u0644\u0623\u0628\u0635\u0627\u0644\u064a\u0627\u062a \u0627\u0644\u0648\u0627\u0637\u0633 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":78,[u.c]:79,[u.z]:80,[u._]:81,[u.a]:82,[u.d]:83,[u.C]:84,[u.s]:85,[u.J]:86,[u.n]:87,[u.P]:88,[u.M]:89,[u.u]:90,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u064a\u0648\u0645 \u0627\u0644\u0623\u062b\u0646\u064a\u0646 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":91,"\u0644\u0628\u0634 \u0622\u062f\u0627\u0645 \u0644\u064a\u0648\u0645 \u0627\u0644\u0627\u062b\u0646\u064a\u0646 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":92,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u064a\u0648\u0645 \u0627\u0644\u062b\u0644\u0627\u062b\u0627\u0621 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":93,"\u0644\u0628\u0634 \u0623\u062f\u0627\u0645 \u0644\u064a\u0648\u0645 \u0627\u0644\u062b\u0644\u0627\u062b\u0627\u0621 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":94,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u064a\u0648\u0645 \u0627\u0644\u0623\u0631\u0628\u0639\u0627\u0621 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":95,"\u0644\u0628\u0634 \u0648\u0627\u0637\u0633 \u0644\u064a\u0648\u0645 \u0627\u0644\u0623\u0631\u0628\u0639\u0627\u0621 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":96,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u064a\u0648\u0645 \u0627\u0644\u062e\u0645\u064a\u0633 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":97,"\u0644\u0628\u0634 \u0648\u0627\u0637\u0633 \u0644\u064a\u0648\u0645 \u0627\u0644\u062e\u0645\u064a\u0633 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":98,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u064a\u0648\u0645 \u0627\u0644\u062c\u0645\u0639\u0629 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":99,"\u0644\u0628\u0634 \u0648\u0627\u0637\u0633 \u0644\u064a\u0648\u0645 \u0627\u0644\u062c\u0645\u0639\u0629 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":100,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":101,"\u0644\u0628\u0634 \u0648\u0627\u0637\u0633 \u0644\u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":102,"\u062e\u062a\u0627\u0645 \u0627\u0644\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0627\u062a \u0627\u0644\u0622\u062f\u0627\u0645 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":103,"\u062e\u062a\u0627\u0645 \u0627\u0644\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0627\u062a \u0627\u0644\u0648\u0627\u0637\u0633 - \u0627\u0644\u0623\u0646\u0628\u0627 \u0631\u0627\u0641\u0627\u0626\u064a\u0644":104,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u0623\u0631\u0628\u0639\u0627\u0621":105,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u062e\u0645\u064a\u0633":106,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u062c\u0645\u0639\u0629":107,"\u0625\u0628\u0635\u0627\u0644\u064a\u0629 \u0627\u0644\u0633\u0628\u062a":108,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u0627\u0644\u062b\u0644\u0627\u062b\u0627\u0621":109,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u0627\u0644\u0623\u0631\u0628\u0639\u0627\u0621":110,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u0627\u0644\u062e\u0645\u064a\u0633":111,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u0627\u0644\u062c\u0645\u0639\u0629":112,"\u062b\u064a\u0624\u0637\u0648\u0643\u064a\u0629 \u0627\u0644\u0633\u0628\u062a":113}
